import{_ as a,c as t,o as e,ah as s}from"./chunks/framework.l36K22_3.js";const g=JSON.parse('{"title":"2018，重新出发","description":"2017，是时候说再见了 按宁哥的说法，2017，我一事无成 无力反驳却机智如我回了俩字儿：蛰伏 但回想过去这一年，还是有很多想要说 这一年，有很长一段时间，犹豫和纠结让负面情绪充斥着我全身，温柔的人呀都悄悄替我接收了，感谢你们，感谢坤哥坤...","frontmatter":{"title":"2018，重新出发","date":"2018-01-02T00:00:00.000Z","category":"diary","tags":["心情"],"slug":"2018-and-start-again","layout":"blog-post","description":"2017，是时候说再见了 按宁哥的说法，2017，我一事无成 无力反驳却机智如我回了俩字儿：蛰伏 但回想过去这一年，还是有很多想要说 这一年，有很长一段时间，犹豫和纠结让负面情绪充斥着我全身，温柔的人呀都悄悄替我接收了，感谢你们，感谢坤哥坤..."},"headers":[],"relativePath":"blog/2018-and-start-again.md","filePath":"blog/posts/diary/2018-and-start-again.md","lastUpdated":1788854523000}'),n={name:"blog/2018-and-start-again.md"};function o(r,p,d,i,_,l){return e(),t("div",null,p[0]||(p[0]=[s("<p>2017，是时候说再见了</p><p>按宁哥的说法，2017，我一事无成</p><p>无力反驳却机智如我回了俩字儿：蛰伏</p><p>但回想过去这一年，还是有很多想要说</p><p>这一年，有很长一段时间，犹豫和纠结让负面情绪充斥着我全身，温柔的人呀都悄悄替我接收了，感谢你们，感谢坤哥坤嫂，能听我唠唠嗑</p><p>这一年，接受自己平庸的那一刻是什么情境？（当我拥有了更开阔的眼界，更高一点的格局，我觉得曾经骄傲的我就像只井底之蛙。而我又不太愿意接受自己是平庸的）而我承认自己的工作效率低下，承认自己一直处于安稳的状态，也承认自己的碌碌无为。也许别人看来自己是相当的努力，但是，这种努力是井底之蛙的努力，工作也是浮浅工作，而不是深度工作。只有承认自己的平庸，才能脚踏实地，表现的再谦逊一些，就像乔帮主所说的那样，stay hungry stay foolish</p><p>这一年，很高兴认识你，懂得人生不只是初见，再见亦是同路人。多认识了几个朋友，也有过美好的夏天，很享受下班骑着电驴带你江边兜风的每个夜晚</p><p>这一年，我不叫宅男，去了户外也去了远方，身体结实且健康</p><p>这一年，我当了舅舅又当了叔叔，这辈分 duang 的一下子就拔起来了</p><p>昨天越来越多，明天越来越少，越长大时间就越宝贵。好朋友是愿意跟你一起浪费时间的人。感谢有你们</p><p>自古深情留不住，总是套路得人心。但我不想忘却初心，懂得感恩</p><p>这世上所有选择和坚持，都伴随着误解和不屑。而我不想成为任何人，我只想成为我自己。</p><p>我希望自己成熟稳重也孩子气，跟公仔说话也能专注。在复杂而浮躁的时代里，做一个简单又认真的人</p><p>帮助过我的人，谢谢你；滴水之恩，永不忘。</p><p>放弃我的人，没关系；是我配不上你。</p><p>爱我的人，谢谢你；我会珍惜。</p><p>讨厌我的人，请继续；没办法，我就这脾气。</p><p>我伤过的人，对不起，我不是故意的。</p><p>骗我的人也就这一回吧！自己想去吧！</p><p>时间真是个好东西：</p><p>验证了对的，见证了错的；懂得了真的，明白了假的……</p><p>我就是我，2018 年我会更开心。</p><p>感谢生命中所有的相遇！</p>",23)]))}const f=a(n,[["render",o]]);export{g as __pageData,f as default};
